import AppKit

struct Clip {
    let id = UUID()
    let text: String
    let date: Date
}

final class ClipboardHistory {
    private let board: NSPasteboard
    private var lastChange: Int
    private(set) var items: [Clip] = []

    // Producer markers documented at https://nspasteboard.org/
    private static let excluded = Set([
        "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type"
    ].map(NSPasteboard.PasteboardType.init(rawValue:)))

    init(board: NSPasteboard) {
        self.board = board
        lastChange = board.changeCount
    }

    var accessDenied: Bool {
        if #available(macOS 15.4, *) { return board.accessBehavior == .alwaysDeny }
        return false
    }

    @discardableResult
    func capture() -> Bool {
        let change = board.changeCount
        guard change != lastChange else { return false }
        lastChange = change
        guard !accessDenied, let types = board.types, Self.excluded.isDisjoint(with: types),
              let text = board.string(forType: .string), !text.isEmpty,
              board.changeCount == change else { return false }
        remember(text)
        return true
    }

    func copy(_ text: String) throws {
        board.clearContents()
        guard board.setString(text, forType: .string) else { throw ToolError("写入系统剪贴板失败") }
        lastChange = board.changeCount
        if !text.isEmpty { remember(text) }
    }

    func clear() { items.removeAll() }

    private func remember(_ text: String) {
        items.removeAll { $0.text.utf8.elementsEqual(text.utf8) }
        items.insert(Clip(text: text, date: Date()), at: 0)
    }
}
